{"command":"cd /tmp/models && python3 -c "
import numpy as np
# Verify no object-dtype payloads (which could smuggle pickles) in the npz files
for i in ['01','02','03','04','05','06','08','09','10']:
    d = np.load(f'model_{i}.npz', allow_pickle=False)
    flags = {k: str(d[k].dtype) for k in d.keys()}
    print(f'sub_{i}', flags)
""}

